function fmt(v,id){if(v==null)return '—';return id==='volume'?v.toFixed(4):id==='dna_kbp'?v.toFixed(2):v>=1e6?(v/1e6).toFixed(2)+'M':Math.round(v).toLocaleString('en-US');}
