async function api(path,signal,body){const r=await dataFetch('/api/minimal'+path,{signal,...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});if(!r.ok){const error=await r.json().catch(()=>({}));throw Error(error.detail||`Spatial data request failed (${r.status})`);}return r.json();}
