const running=()=>['queued','initializing','running'].includes(state.manifest?.status);

function rowAt(t=state.time){let lo=0,hi=state.rows.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(state.rows[mid].time<=t)lo=mid;else hi=mid-1;}return state.rows[lo];}
function setPlaying(v){state.playing=v;$('#play').innerHTML=`<i data-lucide="${v?'pause':'play'}"></i>`;$('#play').setAttribute('aria-label',v?'暂停':'播放');icons();}
