const computeStrip=document.createElement('div');computeStrip.className='local-compute-strip';computeStrip.hidden=true;computeStrip.innerHTML='<div><span id="local-stage"></span><small id="local-progress"></small></div><button type="button" id="local-follow">跟随最新结果</button><button type="button" id="local-stop">停止计算</button>';$('.timeline').before(computeStrip);
const loading=document.createElement('div');loading.className='snapshot-status';loading.hidden=true;$('.workspace').append(loading);
function chart(canvas,metric,large=false){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);const rows=state.rows.filter(r=>r[metric.id]!=null);if(rows.length<2)return;let min=Infinity,max=-Infinity;for(const r of rows){min=Math.min(min,r[metric.id]);max=Math.max(max,r[metric.id]);}const range=Math.max(max-min,Math.abs(max)*.025,1e-8),left=large?65:2,right=large?20:2,top=large?22:6,bottom=large?25:5;min-=range*.1;max+=range*.1;const x=t=>left+t/(state.meta?.times.at(-1)||1)*(w-left-right),y=v=>top+(1-(v-min)/(max-min))*(h-top-bottom);if(large){c.font='16px monospace';c.fillStyle='#978a7b';c.textAlign='right';for(let i=0;i<4;i++){const v=min+(max-min)*i/3;c.fillText(fmt(v,metric.id),left-8,y(v)+5);c.beginPath();c.moveTo(left,y(v));c.lineTo(w-right,y(v));c.strokeStyle='#ddd3c3';c.stroke();}}const buckets=new Map();for(const r of rows){const key=Math.floor(x(r.time)),b=buckets.get(key)||{min:r,max:r,first:r,last:r};b.last=r;if(r[metric.id]<b.min[metric.id])b.min=r;if(r[metric.id]>b.max[metric.id])b.max=r;buckets.set(key,b);}c.beginPath();let first=true;for(const b of buckets.values())for(const r of [...new Set([b.first,b.min,b.max,b.last])].sort((a,b)=>a.time-b.time)){if(first){c.moveTo(x(r.time),y(r[metric.id]));first=false;}else c.lineTo(x(r.time),y(r[metric.id]));}c.strokeStyle=metric.color;c.lineWidth=large?2:1.5;c.stroke();const r=rowAt();if(r?.[metric.id]!=null){c.beginPath();c.moveTo(x(state.time),top);c.lineTo(x(state.time),h-bottom);c.strokeStyle=metric.color+'55';c.stroke();c.beginPath();c.arc(x(state.time),y(r[metric.id]),3,0,Math.PI*2);c.fillStyle=metric.color;c.fill();}}
function render(){const end=state.meta?.times.at(-1)||0;$('#time-current').textContent=$('#time-top').textContent=time(state.time);$('#time-total').textContent='/ '+time(end);$('#time-slider').max=end;$('#time-slider').value=state.time;$('#time-mid').textContent=time(end/2);$('#time-end').textContent=time(end);$('#run-status').textContent=`JCVI-SYN3A / ${state.rep||'—'} · 空间帧 ${state.frame?.index??'—'}`;const row=rowAt();for(const m of metrics){$('#value-'+m.id).textContent=fmt(row?.[m.id],m.id);chart($('#spark-'+m.id),m);}selectionDetails();if($('#detail-dialog').open)renderDetail();}
function select(id,sid=null,voxel=null){state.voxel=voxel;if($('#minimal-species-search'))$('#minimal-species-search').value='';state.selected=id;state.species=sid;view.select(id,sid);$('#selection-card').hidden=!id;$('#isolate').disabled=!id;$('#isolate').setAttribute('aria-pressed','false');document.querySelectorAll('button.component').forEach(b=>b.classList.toggle('active',b.dataset.component===id));if(id){const c=components.find(c=>c.id===id);$('#selected-type').textContent=c.en;$('#selected-name').textContent=c.name;$('#selected-description').textContent=c.description;$('#selected-note').textContent='其他组成可见度可通过滑条调节。';selectionDetails();}}
function selectionDetails(){structureExplorer?.selection(state.selected,state.species?state.meta?.species[state.species-1]:null);if(!state.selected||!state.frame)return;const id=state.selected,items=state.meta.species.filter(s=>s.component===id&&state.frame.counts[s.id-1]>0).sort((a,b)=>state.frame.counts[b.id-1]-state.frame.counts[a.id-1]);let n=items.reduce((s,x)=>s+state.frame.counts[x.id-1],0),unit='格点粒子';if(id==='membrane'){n=state.frame.volume;unit='fL · 外包络占据体积';}if(id==='dna'){n=state.frame.dna_voxel_count;unit='DNA 占据格点';}$('#selected-value').textContent=fmt(n,id==='membrane'?'volume':'count');$('#selected-unit').textContent=unit;$('#selected-note').textContent=state.voxel?'格点坐标 '+state.voxel.join(', ')+' · '+state.voxel.map(x=>(x+.5)*state.meta.spacing_nm).join(', ')+' nm':'其他组成可见度可通过滑条调节。';$('#subtype-panel').hidden=!items.length;$('#subtype-title').textContent='原始物种状态';let search=$('#minimal-species-search');if(!search){search=document.createElement('input');search.id='minimal-species-search';search.placeholder='搜索物种或基因';search.setAttribute('aria-label','搜索物种或基因');search.addEventListener('input',selectionDetails);$('#subtype-panel').insertBefore(search,$('#subtype-legend'));}const query=search.value.trim().toLowerCase();const legend=$('#subtype-legend');legend.className='minimal-species';legend.replaceChildren();for(const s of items.filter(s=>!query||[s.name,s.gene,s.product].filter(Boolean).join(' ').toLowerCase().includes(query))){const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(state.species===s.id));const label=document.createElement('span'),value=document.createElement('b');label.textContent=s.name+(s.gene?' · '+s.gene:'');b.title=s.product||s.name;value.textContent=fmt(state.frame.counts[s.id-1],'count');b.append(label,value);if(id==='protein'&&structureExplorer?.hasStructure(s.name)){const mark=document.createElement('small');mark.className='structure-available-mark';mark.textContent='3D';b.append(mark);}b.onclick=()=>{state.species=state.species===s.id?null:s.id;view.setSpecies(state.species);selectionDetails();};legend.append(b);}$('#subtype-note').textContent='点击物种突出显示。粒子坐标为格点中心，不假设跨帧粒子身份。';}
function warmFrames(index){if(document.hidden||!state.meta)return;const count=state.meta.times.length,direction=index>=lastFrameIndex?1:-1,stride=Math.min(60,Math.max(1,Math.round(state.speed)));lastFrameIndex=index;const indices=[index+direction,index-direction,index+2*direction,index-2*direction,index+3*direction,index+4*direction,index+stride*direction,index+2*stride*direction];frameCache.prefetch([...new Set(indices)].filter(i=>i>=0&&i<count).map(i=>'/api/minimal'+runPath(state.rep)+'/frames/'+i));}
function showFrame(target,{reset=false}={}){
 if(!state.meta?.times.length)return Promise.resolve();if(busy&&!reset)return frameTask||Promise.resolve();
 let lo=0,hi=state.meta.times.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(state.meta.times[mid]<=target)lo=mid;else hi=mid-1;}
 pendingFrame={index:lo,rep:state.rep,meta:state.meta,epoch,sequence:++frameSequence};
 if(frameTask)return frameTask;
 busy=true;
 frameTask=(async()=>{while(pendingFrame){const request=pendingFrame;pendingFrame=null;if(request.epoch!==epoch)continue;if(state.frame?.index===request.index){warmFrames(request.index);continue;}
  const url='/api/minimal'+runPath(request.rep)+'/frames/'+request.index,cacheHit=frameCache.has(url),start=performance.now();
  frameCache.pauseDownload(true);const showLoading=setTimeout(()=>{if(request.epoch===epoch&&!state.frame){loading.textContent='加载原始空间帧';loading.hidden=false;}},600);
  try{const f=await frameCache.get(url);if(request.epoch!==epoch||request.rep!==state.rep||request.sequence!==frameSequence)continue;
   const fetched=performance.now();view.setFrame(f,request.meta);state.framePerformance={cacheHit,waitMS:fetched-start,sceneBuildMS:performance.now()-fetched,worker:f.preparation};state.frame=f;state.voxel=null;state.time=f.time;state.ready=true;$('#scene').style.opacity='';render();renderCompute();warmFrames(request.index);
  }catch(e){if(e.name!=='AbortError'&&request.epoch===epoch&&request.sequence===frameSequence){setPlaying(false);loading.textContent='空间帧加载失败，请重试';toast(e.message);}}
  finally{clearTimeout(showLoading);frameCache.pauseDownload(false);if(request.epoch===epoch)loading.hidden=!!state.frame;}
 }})().finally(()=>{busy=false;frameTask=null;if(pendingFrame){const next=pendingFrame;pendingFrame=null;if(next.epoch===epoch)return showFrame(next.meta.times[next.index],{reset:true});}});return frameTask;
}
async function loadRun(rep){const own=++epoch;pendingFrame=null;frameSequence++;frameCache.clear();lastFrameIndex=0;setPlaying(false);state.rep=rep;state.local=rep.startsWith('local-');state.follow=true;state.manifest=null;state.frame=null;state.meta=null;state.rows=[];state.time=state.desired=0;state.ready=false;select(null);render();$('#scene').style.opacity='.18';loading.textContent=state.local?'正在初始化本地细胞':'加载官方轨迹';loading.hidden=false;computeStrip.hidden=!state.local;try{const [meta,summary]=await Promise.all([api(runPath(rep)),api(runPath(rep)+'/summary')]);if(own!==epoch)return;state.meta=meta;state.manifest=meta.manifest||null;state.summary=summary;state.rows=summary.rows;$('#condition-label').textContent=state.local?meta.manifest.name:`JCVI-syn3A · ${rep}`;$('#data-badge').textContent=state.local?'4DWCM · 本地计算':'4DWCM · 官方空间回放';$('.page-footer>span').textContent=state.local?'4DWCM × JCVI-syn3A / 本地耦合仿真':'4DWCM × JCVI-syn3A / 官方空间轨迹';if(meta.times.length)await showFrame(state.local?meta.times.at(-1):0,{reset:true});sessionStorage.setItem('minimal-replicate',rep);renderCompute();if(state.ready&&!state.local){frameCache.downloadAll(meta.times.map((_,i)=>'/api/minimal'+runPath(rep)+'/frames/'+i));setPlaying(true);}}catch(e){if(own===epoch){loading.textContent='空间轨迹暂不可用';toast(e.message);}}}
function renderCompute(){if(!state.local)return;const m=state.manifest||{},labels={queued:'等待启动',initializing:'生成初始染色体',running:'正在本地计算',completed:'计算完成',failed:'计算失败',cancelled:'计算已停止',interrupted:'计算已中断'};$('#local-stage').textContent=labels[m.status]||'连接计算任务';$('#local-progress').textContent=`${time(m.latest_time||0)} / ${time(m.spec?.duration||0)} · ${m.frames||0} frames · ${m.biological_seconds_per_wall_second?.toFixed(3)||'—'}×`;$('#local-stop').hidden=!running();$('#local-follow').disabled=!state.meta?.times.length;$('#local-follow').setAttribute('aria-pressed',String(state.follow));if(!state.frame){loading.hidden=false;loading.textContent=m.error||labels[m.status]||'正在初始化本地细胞';}}
let pollBusy=false;
async function pollLocal(){if(!state.local||pollBusy)return;pollBusy=true;const rep=state.rep,own=epoch;try{const meta=await api(runPath(rep));if(rep!==state.rep||own!==epoch)return;state.manifest=meta.manifest;if(meta.times.length!==(state.meta?.times.length||0)){const summary=await api(runPath(rep)+'/summary');if(rep!==state.rep||own!==epoch)return;state.meta=meta;state.summary=summary;state.rows=summary.rows;if(state.follow||!state.frame){state.desired=meta.times.at(-1);await showFrame(state.desired);}else render();}renderCompute();}catch(e){if(rep===state.rep)$('#local-stage').textContent='计算连接暂时中断，正在重试';}finally{pollBusy=false;}}
$('#local-follow').onclick=()=>{state.follow=true;setPlaying(false);if(state.meta?.times.length){state.desired=state.meta.times.at(-1);showFrame(state.desired,{reset:true});}renderCompute();};
$('#local-stop').onclick=async()=>{try{state.manifest=await api(runPath(state.rep)+'/cancel',undefined,{});renderCompute();}catch(e){toast(e.message);}};
setInterval(pollLocal,2500);
function setTime(t){if(!state.meta?.times.length)return;state.follow=false;renderCompute();state.desired=Math.max(state.meta.times[0],Math.min(state.meta.times.at(-1),Number(t)||0));return showFrame(state.desired,{reset:true});}
function showDetail(id){detail=id;renderDetail();$('#detail-dialog').showModal();}
function renderDetail(){const m=detailMetrics.find(x=>x.id===detail);if(!m)return;$('#detail-title').textContent=m.name+' · '+m.label;$('#detail-description').textContent=m.description;$('#detail-current').textContent=fmt(rowAt()?.[m.id],m.id)+' '+m.unit+' · '+time(state.time);chart($('#detail-chart'),m,true);$('#detail-end').textContent=time(state.meta?.times.at(-1)||0);$('#detail-extra').textContent=state.local?`${state.manifest?.name} · native solver snapshots`:`LM ${state.rep} · counts CSV ${state.summary?.counts_replicate||'—'} · ${state.summary?.pairing?.samples||0} 个时刻匹配`;$('#detail-source').textContent=state.local?'来源：本机官方耦合求解器；不在帧间插值。':'doi:10.5281/zenodo.15579159 · 原始采样；不在帧间插值。';}
$('#component-list').querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.component));$('#clear-selection').onclick=()=>select(null);$('#focus-selection').onclick=()=>view.focusSelected();$('#selection-detail').onclick=()=>showDetail(({membrane:'volume',dna:'dna_kbp',rna:'rna',rnap:'rnap',ribosome:'active_ribosomes',protein:'protein',state:'state'})[state.selected]);$('#metric-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>showDetail(b.dataset.metric));
$('#play').onclick=()=>{if(!state.ready)return;state.follow=false;renderCompute();if(!state.playing&&state.time>=state.meta.times.at(-1))setTime(0);setPlaying(!state.playing);};$('#time-slider').oninput=e=>setTime(e.target.value);$('#speed').onchange=e=>state.speed=Number(e.target.value);$('#jump-end').onclick=()=>setTime(state.meta?.times.at(-1));$('#cutaway').oninput=e=>{$('#cut-value').value=e.target.value+'%';view.setCut(Number(e.target.value)/100);};$('#explode').onclick=()=>{const on=$('#explode').getAttribute('aria-pressed')!=='true';$('#explode').setAttribute('aria-pressed',on);view.explode(on);$('#exploded-labels').hidden=!on;};$('#isolate').onclick=()=>$('#isolate').setAttribute('aria-pressed',view.isolate());$('#home-view').onclick=()=>view.home();$('#auto-orbit').onclick=()=>{const on=$('#auto-orbit').getAttribute('aria-pressed')!=='true';$('#auto-orbit').setAttribute('aria-pressed',on);view.orbit(on);};$('#quality').onclick=()=>$('#quality').textContent=view.quality()?'HQ':'ECO';$('#screenshot').onclick=()=>{view.screenshot();toast('正在导出高清截图');};
$('#experiment-form').innerHTML=`<div class="dialog-header"><span class="eyebrow">JCVI-SYN3A / 4DWCM</span><button type="button" class="icon-btn close-dialog" aria-label="关闭"><i data-lucide="x"></i></button></div><h2>观察一个最小细胞。</h2><div class="minimal-mode-tabs"><button type="button" data-mode="local" aria-pressed="true">本地计算</button><button type="button" data-mode="reference" aria-pressed="false">官方参考案例</button></div><div id="minimal-local-panel"><p>在计算主机上运行官方耦合模型，持续显示新产生的空间状态。</p><div class="minimal-live-fields"><label>随机种子<input id="minimal-seed" type="number" min="1" max="9999" value="1" required></label><label>生物时间<select id="minimal-duration"><option value="8" selected>8 秒 · 快速验证</option><option value="60">1 分钟</option><option value="600">10 分钟</option><option value="1800">30 分钟</option><option value="7200">120 分钟</option></select></label></div><p class="spatial-note">随机种子用于初始化及 RDME；它不是基因突变。计算速度以实测为准，快进仅适用于已经产生的数据。</p><p id="minimal-capability" class="spatial-note"></p><button type="submit" id="minimal-start" class="primary-btn">启动本地计算</button><p id="minimal-live-error" class="minimal-error" role="alert"></p><h3>本地实验记录</h3><div id="minimal-local-runs" class="minimal-replicates"></div></div><div id="minimal-reference-panel" hidden><p>官方发布的四条独立空间轨迹，保留为参考案例。</p><div id="minimal-replicates" class="minimal-replicates"></div></div>`;
$('#experiment-form .close-dialog').onclick=()=>$('#experiment-dialog').close();
for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>{const local=b.dataset.mode==='local';$('#minimal-local-panel').hidden=!local;$('#minimal-reference-panel').hidden=local;document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};
$('#experiment-form').onsubmit=async e=>{e.preventDefault();const button=$('#minimal-start');button.disabled=true;$('#minimal-live-error').textContent='';try{const m=await api('/live/runs',undefined,{seed:Number($('#minimal-seed').value),duration:Number($('#minimal-duration').value)});$('#experiment-dialog').close();await loadRun(m.id);}catch(error){$('#minimal-live-error').textContent=error.message;}finally{button.disabled=false;}};
$('#experiment-open').onclick=async()=>{try{const [refs,caps,localRuns]=await Promise.all([api('/catalog'),api('/live/capabilities'),api('/live/runs')]);catalog=refs;$('#minimal-live-error').textContent='';$('#minimal-start').disabled=!caps.ready||localRuns.some(r=>['initializing','running','queued'].includes(r.status));$('#minimal-capability').textContent=caps.ready?`本地 GPU 求解器已通过短程验证。短程实测：${(1/caps.validation.biological_seconds_per_wall_second).toFixed(1)} 秒墙钟时间 / 1 秒生物时间。DNA 更新时可能额外等待。`:'本地求解器正在验证，参考案例可以正常观看。';for(const [selector,runs,local] of [['#minimal-replicates',refs.runs,false],['#minimal-local-runs',localRuns,true]]){const list=$(selector);list.replaceChildren();for(const r of runs){const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(r.id===state.rep));b.textContent=local?`${r.name} · ${time(r.latest_time||0)} / ${time(r.spec.duration)} · ${r.status}`:`${r.name} · ${time(r.end)} · ${r.frames} 帧`;b.onclick=()=>{$('#experiment-dialog').close();loadRun(r.id);};list.append(b);}}$('#experiment-dialog').showModal();icons();}catch(e){toast(e.message);}};

function source(){const p=$('#source-dialog');p.querySelector('h2').textContent='空间有来源，精度有边界。';p.querySelectorAll('p').forEach(e=>e.remove());$('#provenance').textContent=state.local?`JCVI-syn3A / LOCAL 4DWCM\n${state.manifest?.name}\n10 nm · ${state.meta?.times.length||0} frames\n${state.time} s · ${state.frame?.particle_count||0} particles`:`JCVI-syn3A / 4DWCM\nLM ${state.rep} ↔ counts CSV ${state.summary?.counts_replicate||'—'}\n10 nm · ${state.meta?.times.length||0} 空间帧\n当前帧 ${state.time} s · 区域网格 ${state.frame?.site_time??'—'} s\n载入 ${state.frame?.particle_count||0} 个非零格点粒子；其他模型状态默认隐藏`;$('#provenance').style.whiteSpace='pre-line';const note=document.createElement('p');note.textContent=(state.local?'当前空间状态由本机官方求解器新计算。代谢指标来自同一次耦合计算。':'粒子位置和区域来自官方 LM 文件。')+'多个粒子可占据同一格点；不添加随机位移，不在帧间插值。DNA 以半透明等值面显示占据区域，不代表染色体链。核糖体占据网格可单独开启。总览中的分子形状、朝向与材质是可视化符号，展开视图改变位置仅用于检查。ATP 等非空间指标使用与当前空间状态对应的模型计数。分裂后的视野可能包含两个子细胞，数据是整个模拟域的总量。';p.insertBefore(note,p.querySelector('.reference-links'));p.querySelector('.reference-links').innerHTML='<a href="https://doi.org/10.1016/j.cell.2026.02.009" target="_blank" rel="noreferrer">论文 ↗</a><a href="https://zenodo.org/records/15579159" target="_blank" rel="noreferrer">官方数据 ↗</a>';p.showModal();}
$('#source-open').onclick=$('#help-open').onclick=source;
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();$('#play').click();}if(e.key==='Home'){e.preventDefault();view.home();}if(e.key==='Escape')select(null);if(e.key.toLowerCase()==='f')view.focusSelected();});
view=await createMinimalView($('#scene'),{onSelect:select,onHover:(id,x,y,sid)=>{const el=$('#hover-label');el.hidden=!id;if(id){el.textContent=components.find(c=>c.id===id).name+(sid?' · '+state.meta.species[sid-1].name:'');el.style.left=Math.min(x+15,$('#scene').clientWidth-200)+'px';el.style.top=Math.min(y+15,$('#scene').clientHeight-50)+'px';}}});icons();
const layers=document.createElement('div');layers.className='minimal-layer-options';layers.innerHTML='<label><input type="checkbox" id="minimal-show-states">显示其他模型状态</label><label><input type="checkbox" id="minimal-show-voxels">显示核糖体占据网格</label>';$('#component-list').after(layers);$('#minimal-show-states').onchange=e=>view.states(e.target.checked);$('#minimal-show-voxels').onchange=e=>view.voxels(e.target.checked);
const structureControls=document.createElement('div');structureControls.id='protein-instances-controls';structureControls.hidden=true;structureControls.innerHTML='<label><input id="protein-instances-enabled" type="checkbox" checked>全部副本使用结构模型</label><p id="protein-instances-status" role="status"></p><small>按真实尺寸显示原子坐标生成的精细预测表面；朝向为示意。其他蛋白质只显示轮廓，可见度 0% 时隐藏。格点重叠保留，P / C_P 同基因状态合并显示，不代表已组装复合体。</small><button id="protein-copy-focus" class="small-btn" type="button" disabled>聚焦一个副本</button>';$('#subtype-panel').before(structureControls);$('#protein-instances-enabled').onchange=e=>view.setProteinStructures(e.target.checked);$('#protein-copy-focus').onclick=()=>{if(!view.focusProteinCopy())toast('当前剖切隐藏了全部副本，请调整剖切深度');};window.addEventListener('proteininstanceschange',e=>{const d=e.detail;structureControls.hidden=state.selected!=='protein';const messages={idle:'选择带 3D 标记的蛋白质，显示其全部副本。',loading:'正在加载共享结构',unavailable:'此蛋白质尚无已核验结构，保留示意造型。',error:'结构加载失败，保留示意造型；请重新选择。',off:'当前使用示意造型',ready:'已按结构显示全部副本'};$('#protein-instances-status').textContent=messages[d.status]+(d.status==='ready'?` · ${d.copies} · ${d.locus}`:'');$('#protein-copy-focus').disabled=d.status!=='ready'||!d.copies;});
window.minimalObservatory={state,view,setPlaying,frameCache:()=>frameCache.debug(),structures:()=>structureExplorer?.debug(),setTime,loadRun,select,ready:()=>state.ready};
try{catalog=await api('/catalog');if(!catalog.ready){loading.hidden=false;loading.textContent='官方空间轨迹正在准备';}else{const saved=sessionStorage.getItem('minimal-replicate');const localRuns=await api('/live/runs');await loadRun([...catalog.runs,...localRuns].some(r=>r.id===saved)?saved:catalog.runs[0].id);}}catch(e){loading.hidden=false;loading.textContent='空间服务暂不可用';toast(e.message);}
let last=performance.now();function tick(now){const dt=Math.min(.5,(now-last)/1000);last=now;if(state.playing&&state.meta?.times.length){state.desired=Math.min(state.meta.times.at(-1),state.desired+dt*state.speed);if(!busy&&Math.floor(state.desired)!==state.time)showFrame(state.desired);if(state.time>=state.meta.times.at(-1))setPlaying(false);}requestAnimationFrame(tick);}requestAnimationFrame(tick);

bindContextOpacity(()=>view);

const cacheStatus=document.createElement('small');cacheStatus.id='frame-cache-status';cacheStatus.style.cssText='display:block;text-align:right;font-size:10px;color:#958778;margin:4px 0';document.querySelector('.timeline')?.after(cacheStatus);
window.addEventListener('frame-download',({detail:d})=>{if(d.status==='idle'){cacheStatus.textContent='';return;}cacheStatus.textContent=(d.status==='complete'?'片段已缓存':d.status==='limited'?'已缓存常用片段，剩余按需读取':d.status==='error'?'后台缓存暂停，仍可按需播放':'后台缓存')+' · '+d.done+'/'+d.total;});
